import { SettingsSubnav } from '@refy-design/web';
import type { SettingsSubnavGroup } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const GROUPS: SettingsSubnavGroup[] = [
  {
    title: 'Personal',
    items: [
      { href: '#account', label: 'Account', description: 'Profile, password, 2FA' },
      {
        href: '#general',
        label: 'Overall',
        description: 'Language, theme, notifications',
      },
    ],
  },
  {
    title: 'Workspace',
    items: [
      { href: '#workspace', label: 'Workspace', description: 'Name, domain, logo' },
      { href: '#team', label: 'Team', description: 'Members and roles' },
      { href: '#projects', label: 'Projects', description: 'Team work areas' },
      { href: '#billing', label: 'Billing', description: 'Plan, payment, invoices' },
    ],
  },
  {
    title: 'Integrations',
    items: [
      { href: '#connectors', label: 'Connectors', description: 'External apps' },
      { href: '#api', label: 'API & Webhooks', description: 'Keys and endpoints' },
    ],
  },
];
export function Example() {
  const args: Pick<ComponentProps<typeof SettingsSubnav>, 'groups' | 'activeHref'> = {
    groups: GROUPS,
    activeHref: '#account',
  };
  const [active, setActive] = useState(args.activeHref);
  return (
    <div style={{ maxWidth: '100%', width: 280 }}>
      <SettingsSubnav
        {...args}
        activeHref={active}
        renderLink={(item, props) => (
          <a
            {...props}
            onClick={(event) => {
              event.preventDefault();
              setActive(item.href);
            }}
          />
        )}
      />
      <p role="status">
        Selected section:{' '}
        {
          GROUPS.flatMap((group) => group.items).find((item) => item.href === active)
            ?.label
        }
      </p>
    </div>
  );
}

